-- Programme d aout 2026 de WAKA UP, encode d apres leur calendrier (image envoyee par Mag).
-- Texte en base64 : le presse-papier vers l editeur SQL abime les accents.
delete from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') and jour >= '2026-08-01' and jour <= '2026-08-31';
select jour, titre, debut from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') order by jour, debut;
